//! The number and date formats of `sermofur_core::format` against the table that the .NET code
//! produced (`rust/tests/golden/formats.json`, regenerated by `rust/tools/format-oracle`).

use proptest::prelude::*;
use serde_json::Value;
use sermofur_core::format::{DateTimeOffset, json_double, parse_json_text, round6};

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/formats.json"
    );
    let text = std::fs::read_to_string(path).expect("the golden file exists");
    serde_json::from_str(&text).expect("the golden file is valid JSON")
}

fn rows(golden: &Value, name: &str) -> Vec<Value> {
    golden[name].as_array().expect("an array").clone()
}

/// A 64-bit integer that the oracle wrote as a string.
fn int(value: &Value) -> i64 {
    value
        .as_str()
        .expect("a string")
        .parse()
        .expect("a 64-bit integer")
}

/// The double of a bit pattern that the oracle wrote as a signed integer string.
fn double_of_bits(value: &Value) -> f64 {
    f64::from_bits(u64::from_ne_bytes(int(value).to_ne_bytes()))
}

fn offset(value: &Value) -> i16 {
    i16::try_from(value.as_i64().expect("a number")).expect("a small offset")
}

#[test]
fn doubles_are_written_like_system_text_json() {
    let rows = rows(&golden(), "doubles");
    assert!(rows.len() > 2000);
    let mut deviations = Vec::new();
    for row in &rows {
        let value = double_of_bits(&row[0]);
        // The .NET text of these two powers of two does not read back as the same double
        // (2^-25 and 2^-958: it drops the last digit of a tie below the lower neighbour's
        // midpoint). The port keeps the round-trip text; see the report of lot 1b.0.
        if row[1]
            .as_str()
            .is_some_and(|t| t.parse::<f64>().ok() != Some(value))
        {
            deviations.push(row[0].as_str().unwrap().to_string());
            continue;
        }
        assert_eq!(
            json_double(value).as_deref(),
            row[1].as_str(),
            "bits {}",
            row[0]
        );
    }
    assert_eq!(
        deviations,
        ["292733975779082240", "4494592428115755008"],
        "the only .NET texts that do not round-trip"
    );
}

#[test]
fn round6_matches_math_round_bit_for_bit() {
    let rows = rows(&golden(), "round6");
    assert!(rows.len() > 400);
    for row in &rows {
        let actual = round6(double_of_bits(&row[0]));
        assert_eq!(
            actual.to_bits(),
            double_of_bits(&row[1]).to_bits(),
            "bits {}",
            row[0]
        );
    }
}

#[test]
fn dates_are_formatted_like_the_dotnet_formats() {
    let rows = rows(&golden(), "dates");
    assert!(rows.len() > 200);
    for row in &rows {
        let date = DateTimeOffset::new(int(&row["utcTicks"]), offset(&row["offsetMinutes"]))
            .expect("a valid golden date");
        let context = row["utcTicks"].to_string();
        let json = format!("\"{}\"", date.to_json_text());
        assert_eq!(json, row["json"].as_str().unwrap(), "{context}");
        assert_eq!(date.to_o(), row["o"].as_str().unwrap(), "{context}");
        assert_eq!(date.to_log(), row["log"].as_str().unwrap(), "{context}");
        assert_eq!(
            date.to_seconds(),
            row["seconds"].as_str().unwrap(),
            "{context}"
        );
        assert_eq!(
            date.to_backup(),
            row["backup"].as_str().unwrap(),
            "{context}"
        );
    }
}

#[test]
fn dates_are_read_like_system_text_json() {
    let rows = rows(&golden(), "parse");
    assert!(rows.len() > 70);
    for row in &rows {
        let input = row["input"].as_str().unwrap();
        let local = row.get("localOffsetMinutes").map_or(60, offset);
        let actual = parse_json_text(input, |_| local);
        let expected = row.get("utcTicks").map(|ticks| {
            DateTimeOffset::new(int(ticks), offset(&row["offsetMinutes"])).expect("valid")
        });
        assert_eq!(actual, expected, "input {input:?}");
    }
}

fn valid_date() -> impl Strategy<Value = DateTimeOffset> {
    (0..=3_155_378_975_999_999_999i64, -840i16..=840)
        .prop_filter_map("local and utc ticks in range", |(ticks, minutes)| {
            DateTimeOffset::new(ticks, minutes)
        })
}

#[test]
fn offset_limits_never_panic() {
    for minutes in [i16::MIN, i16::MAX, -841, 841] {
        assert_eq!(DateTimeOffset::new(0, minutes), None, "{minutes}");
    }
    let mid = 1_000_000_000_000_000_000;
    assert!(DateTimeOffset::new(mid, 840).is_some());
    assert!(DateTimeOffset::new(mid, -840).is_some());
    assert_eq!(DateTimeOffset::new(mid, i16::MIN), None);
}

#[test]
fn the_local_closure_receives_the_local_ticks() {
    let seen = std::cell::Cell::new(None);
    let parsed = parse_json_text("2026-11-06T11:00:00", |ticks| {
        seen.set(Some(ticks));
        60
    })
    .expect("valid");
    // 2026-11-06T11:00:00 as local ticks; the UTC reading is one hour earlier.
    assert_eq!(seen.get(), Some(639_295_596_000_000_000));
    assert_eq!(parsed.utc_ticks(), 639_295_560_000_000_000);
}

#[test]
fn an_explicit_offset_never_calls_the_local_closure() {
    for input in ["2026-11-06T11:00:00Z", "2026-11-06T11:00:00+01:00"] {
        assert!(parse_json_text(input, |_| panic!("called")).is_some());
    }
}

proptest! {
    #[test]
    fn parsing_arbitrary_text_never_panics(text in r"\PC{0,64}", dated in r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.+TZ-]{0,40}", local in any::<i16>()) {
        let _ = parse_json_text(&text, |_| local);
        let _ = parse_json_text(&dated, |_| local);
    }

    #[test]
    fn the_constructor_is_some_exactly_in_range(ticks in any::<i64>(), minutes in any::<i16>()) {
        let max = 3_155_378_975_999_999_999i64;
        let local = i128::from(ticks) + i128::from(minutes) * 600_000_000;
        let valid = minutes.unsigned_abs() <= 840
            && (0..=i128::from(max)).contains(&i128::from(ticks))
            && (0..=i128::from(max)).contains(&local);
        prop_assert_eq!(DateTimeOffset::new(ticks, minutes).is_some(), valid);
    }

    #[test]
    fn written_dates_read_back(date in valid_date()) {
        prop_assert_eq!(parse_json_text(&date.to_json_text(), |_| 0), Some(date));
    }

    #[test]
    fn written_doubles_read_back(value in any::<f64>().prop_filter("finite", |v| v.is_finite())) {
        // Rust reads the .NET exponent form (`1E-05`, `1E+17`) as it is.
        let back: f64 = json_double(value).unwrap().parse().unwrap();
        prop_assert_eq!(back.to_bits(), value.to_bits());
    }
}
